INSERT INTO feature VALUES('wildcards','checking','Wildcards: terms the equations force','implicit-arguments','implemented','ordinary',NULL,'`_` written where a value is read, in a call''s argument, an instantiation slot or an ascription''s type, stands for the term the equations force, the elaborator''s to answer where a hole is the author''s: it is a metavariable of the solver omitted implicits use, bound only where a comparison forces a most general solution, and the body is emitted with that term written, so the kernel never meets it. A wildcard an ascription''s type holds is forced by the term ascribed, through reflexivity''s endpoints or the value bridge. A constructor written in a field of a constructor whose type a call computes takes its own family over one wildcard the lowering inserts for each parameter and index, forced by the call the checker reduces. Its hole is named as a wildcard''s, apart from an omitted implicit''s, so a body printed before the checker fills it writes each wildcard back as `_`. A wildcard nothing forces is ImplicitUnsolved, and one where a computation or a type is read is a form of the wrong sort.','surface-grammar surface-lowering core-term core-checker surface-pretty surface-diagnostics','corpus/model/holes/wildcard.gandr corpus/pathological/holes/wildcard.gandr corpus/ledger/syntax/wildcard.expression.gandr corpus/model/data/computed-pair-field.gandr crates/surface-lowering/src/lower/implicit/tests.rs::a_wildcard_emits_the_body_written_by_hand_528 crates/surface-lowering/src/lower/native/tests.rs::a_pair_in_a_field_at_a_computed_pair_type_takes_its_family_over_wildcards_6113 crates/surface-pretty/tests/goldens.rs::a_call_writes_the_wildcards_it_holds_528 crates/core-checker-bridge/src/bridge/tests.rs::an_ascription_solves_the_wildcard_its_type_holds_1979','corpus/model/holes/wildcard.gandr',NULL);
